def original_dependencies():
    """Return verified relative-path/bytes pairs; no host paths or SDK imports."""
    if len(MANIFEST) != len(_ENCODED):
        raise ValueError("Incomplete original Recovery dependency archive")
    result = []
    for record, encoded in zip(MANIFEST, _ENCODED):
        raw = zlib.decompress(base64.b85decode(encoded))
        if (len(raw) != record["bytes"]
                or hashlib.sha256(raw).hexdigest() != record["sha256"]):
            raise ValueError("Original Recovery dependency archive hash mismatch")
        result.append((record, raw))
    return result

